import AppKit
import SwiftUI

public struct AppLogo {
    public static let base64Data = ""

    public static var nsImage: NSImage {
        // 1. Load from AppIcon.icns in main bundle
        if let bundlePath = Bundle.main.path(forResource: "AppIcon", ofType: "icns"),
           let img = NSImage(contentsOfFile: bundlePath) {
            return img
        }
        // 2. Load from named AppIcon
        if let icon = NSImage(named: "AppIcon") {
            return icon
        }
        // 3. Base64 fallback: travels inside the binary, so there is no
        //    machine-specific path to depend on.
        if let data = Data(base64Encoded: base64Data),
           let img = NSImage(data: data) {
            return img
        }
        return NSImage()
    }

    public static var image: Image {
        Image(nsImage: nsImage)
    }
}
